# Generated by build.py from recipe.yml for recipe ftp-choose-how-curl-walks-folders. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site/a/b/c', 'site/d/e/f', 'site/g/h/i', 'site/locked/in' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/a/b/c/one.txt'), "one`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/d/e/f/two.txt'), "two`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/g/h/i/three.txt'), "three`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/locked/in/there.txt'), "there`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--directory', 'site', '-v', '--log-file', 'site/surl.log', '--fault', '"error;scheme=ftp;command=CWD;path=/locked;reply=550', 'CWD', 'is', 'not', 'allowed', 'here"', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --ftp-method multicwd ftp://127.0.0.1:8080/a/b/c/one.txt --next -sS --ftp-method singlecwd ftp://127.0.0.1:8080/d/e/f/two.txt --next -sS --ftp-method nocwd ftp://127.0.0.1:8080/g/h/i/three.txt } finally { Stop-Process $server0 }
